namespace ghidra.app.plugin.core.memory;







using docking;
using ghidra.app.util;
using ghidra.framework.cmd;
using ghidra.framework.plugintool;
using ghidra.framework.store;
using ghidra.program.database;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util;
using ghidra.util.layout;

class ImageBaseDialog : DialogComponentProvider {
	private JTextField textField;
	private Address addr;
	private Address currentAddr;
	private Program program;
	private PluginTool tool;

	ImageBaseDialog(PluginTool tool, Program program, Address currentAddr) : base("Base Image Address", true, true, true, false)
    {
		this.program = program;
		this.currentAddr = currentAddr;
		this.tool = tool;
		addr = currentAddr;

		addWorkPanel(createWorkPanel());
		addOKButton();
		addCancelButton();
		rootPanel.setPreferredSize(new Dimension(240, 120));

		setHelpLocation(new HelpLocation(HelpTopics.MEMORY_MAP, "Set Image Base"));
		setFocusComponent(textField);
	}

	/* @Override */
	public void dispose() {
		base.dispose();
		tool = null;
		program = null;
	}

	private JComponent createWorkPanel() {
		JPanel panel = new JPanel(new MiddleLayout());
		textField = new JTextField(20);
		textField.setText(currentAddr.toString());
		textField.getAccessibleContext().setAccessibleName("Image Base Address");

		textField.selectAll();
		textField.addActionListener(e => {
			if (addr != null) {
				okCallback();
			}
		});
		panel.add(textField);

		textField.getDocument().addDocumentListener(new _Anon_DocumentListener_1());
		return panel;
	}

	private void updateAddress() {
		clearStatusText();
		string addrString = textField.getText();
		addr = null;
		try {
			addr = program.getAddressFactory().getDefaultAddressSpace().getAddress(addrString);
		}
		catch (AddressFormatException e) {
			// handled below
		}
		if (addr == null) {
			setStatusText("Invalid Address");
		}
		setOkEnabled(addr != null);
	}

	/* @Override */
	protected void okCallback() {
		if (addr != null && !addr.equals(currentAddr)) {
			Msg.info(this, "old base = " + program.getImageBase());
			SetBaseCommand cmd = new SetBaseCommand(addr);
			if (!tool.execute(cmd, program)) {
				setStatusText(cmd.getStatusMsg());
				return;
			}
			Msg.info(this, "new base = " + ((ProgramDB) program).getImageBase());
		}
		close();
	}

}

class SetBaseCommand : Command<Program> {
	private Address addr;
	private string msg;

	SetBaseCommand(Address addr) {
		this.addr = addr;
	}

	/**
	 * @see ghidra.framework.cmd.Command#applyTo(ghidra.framework.model.DomainObject)
	 */
	/* @Override */
	public bool applyTo(Program program) {
		try {
			program.setImageBase(addr, true);
		}
		catch (IllegalStateException e) {
			msg = e.getMessage();
			return false;
		}
		catch (AddressOverflowException e) {
			msg = "Image base of " + addr.toString() + " not allowed; change causes " +
				e.getMessage();
			return false;
		}
		catch (LockException e) {
			msg = "Must have exclusive checkout to set the image base";
			return false;
		}
		return true;
	}

	/* @Override */
	public string getStatusMsg() {
		return msg;
	}

	/* @Override */
	public string getName() {
		return "Set Image Base";
	}

	internal class _Anon_DocumentListener_1 : DocumentListener
	{

			/* @Override */
			public void changedUpdate(DocumentEvent e) {
				updateAddress();
			}

			/* @Override */
			public void insertUpdate(DocumentEvent e) {
				updateAddress();
			}

			/* @Override */
			public void removeUpdate(DocumentEvent e) {
				updateAddress();
			}
		
	}

}
